import json
import socket
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOG_PATH = "/tmp/recon/anomalies.log"
MAX_HARD_FAILURES = 25      # consecutive non-429/non-auth failures before giving up loudly
MAX_RATE_LIMIT_WAITS = 500  # sanity cap so a broken server cannot spin forever


def log(msg):
    line = time.strftime("%H:%M:%S ") + msg
    with open(LOG_PATH, "a") as f:
        f.write(line + "\n")
    print(line, flush=True)


class Client:
    def __init__(self):
        self.token = None
        self.stats = {"requests": 0, "ok": 0, "429": 0, "auth_refresh": 0, "other_fail": 0, "tokens": 0}

    # -- low level -----------------------------------------------------------------
    def _raw(self, method, path, use_token=True, timeout=20):
        req = urllib.request.Request(BASE + path, method=method, data=b"" if method == "POST" else None)
        if use_token and self.token:
            req.add_header("Authorization", "Bearer " + self.token)
        self.stats["requests"] += 1
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()
        except (urllib.error.URLError, socket.timeout, ConnectionError, OSError) as e:
            return None, {}, repr(e).encode()

    def new_token(self):
        for attempt in range(1, 30):
            status, headers, body = self._raw("POST", "/token", use_token=False)
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                    self.token = tok
                    self.stats["tokens"] += 1
                    return tok
                except Exception:
                    pass
            if status == 429:
                self._sleep_for(headers, body, "POST /token")
                continue
            log(f"token request problem (attempt {attempt}): status={status} body={body[:200]!r}")
            time.sleep(min(2 * attempt, 10))
        raise RuntimeError("could not obtain a token")

    @staticmethod
    def _retry_after(headers, body):
        waits = []
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    waits.append(float(v))
                except ValueError:
                    pass
        try:
            ra = json.loads(body).get("retry_after")
            if isinstance(ra, (int, float)):
                waits.append(float(ra))
        except Exception:
            pass
        return max(waits) if waits else 1.0

    def _sleep_for(self, headers, body, what):
        wait = self._retry_after(headers, body)
        self.stats["429"] += 1
        log(f"429 on {what}: waiting {wait}s (headers Retry-After={headers.get('Retry-After')!r}, body={body[:120]!r})")
        time.sleep(wait + 0.1)

    # -- high level ----------------------------------------------------------------
    def get_json(self, path, validate=None, allow_404=False):
        """GET path -> parsed JSON. Retries until a valid 200 arrives (or a confirmed 404 if allowed)."""
        if self.token is None:
            self.new_token()
        hard_failures = 0
        rate_waits = 0
        not_found = 0
        while True:
            status, headers, body = self._raw("GET", path)

            if status == 200:
                try:
                    data = json.loads(body)
                    if validate is not None:
                        validate(data)
                    self.stats["ok"] += 1
                    return data
                except Exception as e:
                    log(f"200 but unusable body on {path}: {e!r} body={body[:300]!r}")
                    # could be a disguised auth/expiry error; fall through to the hard-failure path
                    hard_failures += 1
                    if hard_failures % 3 == 0:
                        self.new_token()
                        self.stats["auth_refresh"] += 1
            elif status == 429:
                rate_waits += 1
                if rate_waits > MAX_RATE_LIMIT_WAITS:
                    raise RuntimeError(f"rate limited too many times on {path}")
                self._sleep_for(headers, body, path)
                continue
            elif status in (401, 403):
                log(f"{status} on {path} (token {self.token!r}): body={body[:300]!r} headers={headers} -> fetching new token")
                self.stats["auth_refresh"] += 1
                self.new_token()
                continue
            elif status == 404 and allow_404:
                not_found += 1
                if not_found >= 3:  # confirm it is persistent, not a transient glitch
                    log(f"404 confirmed {not_found}x on {path}: body={body[:200]!r}")
                    return None
                log(f"404 on {path} (seen {not_found}x), re-checking: body={body[:200]!r}")
                time.sleep(0.5)
                continue
            else:
                self.stats["other_fail"] += 1
                log(f"HTTP {status} on {path}: body={body[:300]!r} headers={headers}")
                hard_failures += 1

            if hard_failures >= MAX_HARD_FAILURES:
                raise RuntimeError(f"giving up on {path} after {hard_failures} failures (last status {status})")
            time.sleep(min(0.5 * hard_failures, 5))

