"""Fetch every page of /orders and cache the raw JSON of each page under /tmp/recon/data/."""
import json
import os
import sys

from client import Client, log

DATA = "/tmp/recon/data"


def validate_page(d):
    for k in ("page", "total_pages", "items", "next"):
        if k not in d:
            raise ValueError(f"missing key {k!r}")
    if not isinstance(d["items"], list):
        raise ValueError("items is not a list")


def main():
    c = Client()
    c.new_token()
    first = c.get_json("/orders?page=1", validate=validate_page)
    total_pages = first["total_pages"]
    log(f"total_pages reported by page 1: {total_pages}")

    pages = {1: first}
    page = 2
    while page <= total_pages:
        d = c.get_json(f"/orders?page={page}", validate=validate_page)
        if d["page"] != page:
            raise RuntimeError(f"asked for page {page} but got page {d['page']}")
        if d["total_pages"] != total_pages:
            log(f"NOTE: total_pages changed from {total_pages} to {d['total_pages']} at page {page}")
            total_pages = max(total_pages, d["total_pages"])
        pages[page] = d
        page += 1

    # structural checks on `next`
    for p in sorted(pages):
        nxt = pages[p]["next"]
        expected = f"/orders?page={p + 1}" if p < total_pages else None
        if nxt != expected:
            log(f"NOTE: page {p} has next={nxt!r}, expected {expected!r}")

    # probe one past the end, to be sure nothing is hiding there
    beyond = c.get_json(f"/orders?page={total_pages + 1}", validate=validate_page, allow_404=True)
    if beyond is None:
        log(f"page {total_pages + 1}: 404 (nothing beyond the last page)")
    else:
        log(f"page {total_pages + 1}: items={len(beyond['items'])} next={beyond['next']!r} total_pages={beyond['total_pages']}")
        pages[total_pages + 1] = beyond

    for p, d in pages.items():
        with open(os.path.join(DATA, f"orders_page_{p:03d}.json"), "w") as f:
            json.dump(d, f)

    log(f"saved {len(pages)} pages; item counts: {[len(pages[p]['items']) for p in sorted(pages)]}")
    log(f"client stats: {c.stats}")


if __name__ == "__main__":
    sys.exit(main())

